 {view==='team'&&owner&&<><div className="section-toolbar"><div><h2>{state.members.length} в команде</h2><p className="muted">Продавцы видят только свои продажи и начисления</p></div><button className="button primary" onClick={()=>open('member')}><Plus size={17}/> Пригласить сотрудника</button></div><section className="panel"><div className="table-scroll"><table><thead><tr><th>Сотрудник</th><th>Email для входа</th><th>Роль</th><th>Доступ</th><th/></tr></thead><tbody>{state.members.map((p:Row,i:number)=><tr key={p.id}><td><div className="person-cell"><Avatar name={p.name} index={i}/><div><strong>{p.name}</strong><small>{p.demo?'Демо-профиль':p.user_id?'Аккаунт подключён':'Ожидает первого входа'}</small></div></div></td><td className="muted">{p.email}</td><td>{p.role==='owner'?'Владелец':'Продавец'}</td><td><span className={'badge '+(p.active?'approved':'rejected')}><i/>{p.active?'Активен':'Отключён'}</span></td><td>{p.role==='staff'&&!p.user_id&&!p.demo&&p.active===1&&<button className="text-button invite-renew" disabled={busy} onClick={()=>run('inviteLink',{memberId:p.id},'Создана новая ссылка. Старая больше не действует.')}>Новая ссылка</button>}{p.role!=='owner'&&<button className="text-button" disabled={busy} onClick={()=>run('member',{id:p.id,active:!p.active},p.active?'Доступ сотрудника отключён':'Доступ восстановлен')}>{p.active?'Отключить':'Восстановить'}</button>}</td></tr>)}</tbody></table></div></section><div className="info-note"><ShieldCheck size={18}/> Продавцы видят свои продажи и начисления, каталог и общий рейтинг. Управление командой и правилами доступно только владельцу.</div></>}
 {view==='plans'&&<><div className="section-toolbar"><div><h2>Фокус на результате</h2><p className="muted">Неделя, месяц и год — независимые цели</p></div>{owner&&<button className="button primary" onClick={()=>open('plan')}><Plus size={17}/> Поставить цель</button>}</div><div className="plans-grid">{state.plans.filter((p:Row)=>p.start<=addDays(week,6)&&p.end>=week).map((p:Row)=>{const relevant=sales.filter(s=>s.status==='approved'&&s.sold_on>=p.start&&s.sold_on<=p.end&&(p.member_id==='team'||p.member_id===s.member_id));const isHiddenTeam=!owner&&p.member_id==='team';const n=relevant.filter(s=>s.category==='laptop').length,rev=relevant.reduce((a,s)=>a+s.price,0),pct=p.target?Math.round(n/p.target*100):p.revenue?Math.round(rev/p.revenue*100):0;return <section key={p.id} className="panel plan-card"><div className="plan-top"><span className="plan-symbol"><Target size={22}/></span><span className="badge neutral">{{week:'Неделя',month:'Месяц',year:'Год'}[p.kind as string]}</span></div><h3>{p.member_id==='team'?'Весь магазин':state.members.find((m:Row)=>m.id===p.member_id)?.name}</h3><p>{shortDate(p.start)} — {shortDate(p.end)} {p.end.slice(0,4)}</p>{isHiddenTeam?<div className="info-note">Общая цель: {p.target} ноутбуков{p.revenue>0?' · '+cash(p.revenue)+' сом':''}. Детальные результаты магазина доступны владельцу.</div>:<><div className="plan-progress"><strong>{pct}%</strong><span>{p.target?n+' / '+p.target+' шт.':cash(rev)+' / '+cash(p.revenue)+' сом'}</span></div><div className="progress-track"><span style={{width:Math.min(pct,100)+'%'}}/></div><div className="plan-bottom">{p.revenue>0?<span>Выручка {cash(rev)} / {cash(p.revenue)} сом</span>:<span>{p.target>n?'Осталось '+(p.target-n)+' шт.'+pace(p,p.target-n):'Цель достигнута'}</span>}<CheckCircle2 size={16}/></div></>}</section>})}</div>{!state.plans.some((p:Row)=>p.start<=addDays(week,6)&&p.end>=week)&&<section className="panel"><Empty title="Пока нет целей на этот период" subtitle="План помогает команде видеть следующий шаг."/></section>}</>}
